SELECT * FROM customer limit 16;

-- 1. what is the total revenue generated by male vs. female customers?

SELECT gender, concat('$ ', sum(purchase_amount)) as total_revenue
FROM customer
GROUP BY  gender;


-- 2. which customers used a discount but still spent more than the average purchase amount?

SELECT customer_id, purchase_amount
FROM customer 
WHERE discount_applied = 'Yes' 
	AND purchase_amount > ( SELECT AVG(purchase_amount) 
                            FROM customer
                            );


-- 3. which are the top 5 products with the highest average review rating?

SELECT item_purchased, ROUND(AVG(review_rating), 2) AS avg_rating
FROM customer 
GROUP BY item_purchased 
ORDER BY avg(review_rating) DESC
LIMIT 5;


-- 4. compare the average purchase amounts between standard and express shipping.

select shipping_type, round(avg(purchase_amount), 2) as avg_amt
from customer 
where shipping_type in ('Standard', 'Express')
group by shipping_type;


-- 5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select subscription_status, 
		count(customer_id) as total_customers,
		round(avg(purchase_amount), 2) as avg_amount,
        round(sum(purchase_amount), 2) as total_revenue
from customer
group by subscription_status
order by total_revenue, avg_amount desc;


-- 6. which 5 products have the highest percentage of purchases with discounts applied?

select item_purchased,
		round((sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*))*100, 2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;


-- 7. Segment customers into New, Returning, and Loyal based on their total revenue between previous purchases, and show the count of each segment.
with cust_type as (
	select customer_id, previous_purchases,
			case 
				when previous_purchases < 2 then 'New'
                when previous_purchases between 2 and 10 then 'Returning'
                else 'Loyal'
                end as cust_segment
	from customer
    )
    
select cust_segment, count(*) as no_of_customers
from cust_type
group by cust_segment;



-- 8. what are the top 3 most purchased products within each category?
with item_counts as (
	select category, item_purchased, count(customer_id) as total_orders,
   row_number() over(partition by category order by count(customer_id) desc) as item_rank
	from customer
    group by category , item_purchased
)	
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <=3;



-- 9. are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select subscription_status, count(customer_id) as repeated_buyers
from customer
where previous_purchases > 5
group by subscription_status; 


-- 10. what is the revenue contribution of each age group?

select age_group, sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;
